import os,re,json,sys
ROOT='snapshots/s12'
pat_tasklet = re.compile(r'\btasklet_init\s*\(\s*([^,]+)\s*,\s*([A-Za-z_0-9]+)\s*,')
pat_decl = re.compile(r'DECLARE_TASKLET(_HI)?\s*\(\s*([A-Za-z_0-9]+)\s*,\s*([A-Za-z_0-9]+)\s*,')
pat_napi_add = re.compile(r'netif_napi_add\s*\(\s*[^,]+,\s*([^,]+),\s*([A-Za-z_0-9]+)\s*,')

tasklet_files={}
for dp,dn,fn in os.walk(ROOT):
    for f in fn:
        if not f.endswith('.c'): continue
        p=os.path.join(dp,f)
        t=open(p,errors='ignore').read()
        hit=False
        for m in pat_tasklet.finditer(t):
            tasklet_files.setdefault(p,[]).append(('tasklet_init',m.group(2))); hit=True
        for m in pat_decl.finditer(t):
            tasklet_files.setdefault(p,[]).append(('DECLARE_TASKLET',m.group(3))); hit=True
        for m in pat_napi_add.finditer(t):
            tasklet_files.setdefault(p,[]).append(('napi_add',m.group(2))); hit=True
print(len(tasklet_files),"files with softirq callbacks")
for p in sorted(tasklet_files):
    print(p, tasklet_files[p])
